package com.portfolio.features.asset.entity; import com.portfolio.features.portfolio.entity.Portfolio; import com.portfolio.features.project.entity.Project; import jakarta.persistence.*; import java.time.*; import java.util.*; import lombok.*; @Entity @Table(name="portfolio_assets") @Getter @Setter @NoArgsConstructor public class PortfolioAsset{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="project_id") private Project project;private String assetType;@Column(name="object_key") private String objectKey;private String originalFilename,contentType;private long fileSize;private LocalDateTime createdAt,updatedAt;@PrePersist void c(){createdAt=updatedAt=LocalDateTime.now();}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}
